 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the separator with equal-sized panels on its two sides.
    cut = None
    axis = None
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - 1 - r:
            cut, axis = r, 'row'
            break
    if cut is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and c == w - 1 - c:
                cut, axis = c, 'col'
                break
    # More generally, the separator is centrally placed between equal-sized panels.
    if cut is None:
        for r in range(h):
            if len(set(grid[r])) == 1 and r < h and h-r-1 == r:
                cut, axis = r, 'row'
                break
    if cut is None:
        for c in range(w):
            if len({row[c] for row in grid}) == 1 and c == w-1-c:
                cut, axis = c, 'col'
                break
    if axis == 'row':
        a, b = grid[:cut], grid[cut+1:]
    else:
        a = [row[:cut] for row in grid]
        b = [row[cut+1:] for row in grid]
    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    # Select the shared panel color most often occurring, excluding the separator.
    bg = max(shared, key=lambda x: sum(v == x for row in a for v in row) + sum(v == x for row in b for v in row))
    return [[3 if x == y else bg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
